body.script:
// Tab Switcher Logic
function switchTab(tabName) {
    // Hide all tab contents
    document.querySelectorAll('.tab-content').forEach(el => el.classList.add('hidden'));

    // Reset tab button styles
    document.querySelectorAll('.tab-btn').forEach(btn => {
        btn.classList.remove('bg-coffee-500', 'text-white', 'shadow-md');
        btn.classList.add('bg-coffee-800/60', 'text-coffee-300');
    });

    // Show selected tab content
    document.getElementById('tab-' + tabName).classList.remove('hidden');

    // Highlight selected tab button
    const activeBtn = document.getElementById('btn-' + tabName);
    activeBtn.classList.remove('bg-coffee-800/60', 'text-coffee-300');
    activeBtn.classList.add('bg-coffee-500', 'text-white', 'shadow-md');
}

// Initialize Chart.js Sales Graph
window.onload = function() {
    const ctx = document.getElementById('salesChart').getContext('2d');

    // Gradient fill for chart area
    const gradient = ctx.createLinearGradient(0, 0, 0, 160);
    gradient.addColorStop(0, 'rgba(224, 169, 109, 0.4)');
    gradient.addColorStop(1, 'rgba(224, 169, 109, 0.0)');

    new Chart(ctx, {
        type: 'line',
        data: {
            labels: ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min'],
            datasets: [{
                label: 'Penjualan (Ribuan Rp)',
                data: [120, 150, 180, 140, 260, 380, 420],
                borderColor: '#e0a96d',
                borderWidth: 3,
                pointBackgroundColor: '#f3e9dc',
                pointBorderColor: '#8b5a2b',
                pointRadius: 4,
                fill: true,
                backgroundColor: gradient,
                tension: 0.4
            }]
        },
        options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
                legend: { display: false }
            },
            scales: {
                x: {
                    grid: { display: false },
                    ticks: { color: '#d9a066', font: { size: 10 } }
                },
                y: {
                    grid: { color: 'rgba(255, 255, 255, 0.05)' },
                    ticks: { color: '#d9a066', font: { size: 10 } }
                }
            }
        }
    });
};
